1	package httpapi
2	
3	import (
4		"errors"
5		"net/http"
6		"strconv"
7		"time"
8	
9		"github.com/cocosolocoder/signalroom/internal/events"
10	)
11	
12	// step bounds for the required integer step parameter, in seconds.
13	const (
14		minStepSeconds = 1
15		maxStepSeconds = 86400
16	)
17	
18	type compareResponse struct {
19		BaselineTotal    int                 `json:"baseline_total"`
20		ObservationTotal int                 `json:"observation_total"`
21		Difference       int                 `json:"difference"`
22		Ratio            *float64            `json:"ratio"`
23		Segments         []compareSegmentDTO `json:"segments"`
24	}
25	
26	type compareSegmentDTO struct {
27		BaselineSince    string `json:"baseline_since"`
28		BaselineUntil    string `json:"baseline_until"`
29		Since            string `json:"since"`
30		Until            string `json:"until"`
31		BaselineCount    int    `json:"baseline_count"`
32		ObservationCount int    `json:"observation_count"`
33		Difference       int    `json:"difference"`
34	}
35	
36	func (h *Handler) compareEvents(w http.ResponseWriter, r *http.Request) {
37		if r.Method != http.MethodGet {
38			w.Header().Set("Allow", "GET")
39			writeError(w, http.StatusMethodNotAllowed, "method not allowed")
40			return
41		}
42		if h.unavailable() {
43			writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
44			return
45		}
46	
47		values := r.URL.Query()
48	
49		// Each timestamp must be present exactly once and parse as RFC3339Nano;
50		// presence for a parameter is validated before moving to the next one.
51		parseParam := func(name string) (time.Time, bool) {
52			raw, ok := singleValue(values, name)
53			if !ok || raw == "" {
54				writeError(w, http.StatusBadRequest, name+" is required and must be a single RFC3339Nano timestamp")
55				return time.Time{}, false
56			}
57			parsed, err := time.Parse(time.RFC3339Nano, raw)
58			if err != nil {
59				writeError(w, http.StatusBadRequest, name+" must be an RFC3339Nano timestamp")
60				return time.Time{}, false
61			}
62			return parsed, true
63		}
64		baselineStart, ok := parseParam("baseline_since")
65		if !ok {
66			return
67		}
68		baselineEnd, ok := parseParam("baseline_until")
69		if !ok {
70			return
71		}
72		observedStart, ok := parseParam("since")
73		if !ok {
74			return
75		}
76		observedEnd, ok := parseParam("until")
77		if !ok {
78			return
79		}
80	
81		rawStep, ok := singleValue(values, "step")
82		if !ok || rawStep == "" {
83			writeError(w, http.StatusBadRequest, "step is required and must be a single integer number of seconds")
84			return
85		}
86		if !isDecimal(rawStep) {
87			writeError(w, http.StatusBadRequest, "step must be an integer from 1 to 86400 seconds")
88			return
89		}
90		stepSeconds, err := strconv.ParseInt(rawStep, 10, 64)
91		if err != nil || stepSeconds < minStepSeconds || stepSeconds > maxStepSeconds {
92			writeError(w, http.StatusBadRequest, "step must be an integer from 1 to 86400 seconds")
93			return
94		}
95	
96		query := events.CompareQuery{
97			Service:       values.Get("service"),
98			Severity:      values.Get("severity"),
99			BaselineSince: baselineStart,
100			BaselineUntil: baselineEnd,
101			Since:         observedStart,
102			Until:         observedEnd,
103			Step:          time.Duration(stepSeconds) * time.Second,
104		}
