3	import (
4		"fmt"
5		"os"
6		"time"
7	
8		"github.com/cocosolocoder/signalroom/internal/events"
9	)
10	
11	func main() {
12		if len(os.Args) < 2 {
13			usage()
14		}
15		var err error
16		switch os.Args[1] {
17		case "demo":
18			if len(os.Args) != 2 {
19				usage()
20			}
21			err = runDemo()
22		case "serve":
23			err = runServe(os.Args[2:])
24		default:
25			usage()
26		}
27		if err != nil {
28			fmt.Fprintf(os.Stderr, "signalroom: %v\n", err)
29			os.Exit(1)
30		}
31	}
32	
33	func usage() {
34		fmt.Fprintln(os.Stderr, "usage: signalroom demo")
35		fmt.Fprintln(os.Stderr, "       signalroom serve --addr <address> --data <directory>")
36		os.Exit(2)
37	}
38	
39	func runDemo() error {
40		store := events.NewStore()
41		base := time.Date(2026, time.October, 1, 10, 0, 0, 0, time.FixedZone("CST", 8*60*60))
42		fixtures := []events.Event{
43			{ID: "evt-001", Service: "gateway", Severity: "critical", Message: "错误率超过阈值", At: base},
44			{ID: "evt-002", Service: "checkout", Severity: "warning", Message: "请求延迟持续升高", At: base.Add(90 * time.Second)},
45			{ID: "evt-003", Service: "gateway", Severity: "info", Message: "值班工程师已确认告警", At: base.Add(3 * time.Minute)},
46		}
47		for _, event := range fixtures {
48			if err := store.Add(event); err != nil {
49				return err
50			}
51		}
52	
53		fmt.Println("Signalroom 服务可观测与事件响应工作台")
54		fmt.Println("当前事件时间线：")
55		for _, event := range store.Query(events.Query{}) {
