package main

import (
	"fmt"
	"os"
	"time"

	"github.com/cocosolocoder/signalroom/internal/events"
)

func main() {
	if len(os.Args) < 2 {
		usage()
	}
	var err error
	switch os.Args[1] {
	case "demo":
		if len(os.Args) != 2 {
			usage()
		}
		err = runDemo()
	case "serve":
		err = runServe(os.Args[2:])
	default:
		usage()
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "signalroom: %v\n", err)
		os.Exit(1)
	}
}

func usage() {
	fmt.Fprintln(os.Stderr, "usage: signalroom demo")
	fmt.Fprintln(os.Stderr, "       signalroom serve --addr <address> --data <directory>")
	os.Exit(2)
}

func runDemo() error {
	store := events.NewStore()
	base := time.Date(2026, time.October, 1, 10, 0, 0, 0, time.FixedZone("CST", 8*60*60))
	fixtures := []events.Event{
		{ID: "evt-001", Service: "gateway", Severity: "critical", Message: "错误率超过阈值", At: base},
		{ID: "evt-002", Service: "checkout", Severity: "warning", Message: "请求延迟持续升高", At: base.Add(90 * time.Second)},
		{ID: "evt-003", Service: "gateway", Severity: "info", Message: "值班工程师已确认告警", At: base.Add(3 * time.Minute)},
	}
	for _, event := range fixtures {
		if err := store.Add(event); err != nil {
			return err
		}
	}

	fmt.Println("Signalroom 服务可观测与事件响应工作台")
	fmt.Println("当前事件时间线：")
	for _, event := range store.Query(events.Query{}) {
		fmt.Printf("%s  %-8s %-8s %s\n", event.At.Format("15:04:05"), event.Service, event.Severity, event.Message)
	}
	fmt.Printf("已接入事件：%d，严重事件：%d\n", len(fixtures), len(store.Query(events.Query{Severity: "critical"})))
	return nil
}

package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"net"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/cocosolocoder/signalroom/internal/events"
	"github.com/cocosolocoder/signalroom/internal/httpapi"
	"github.com/cocosolocoder/signalroom/internal/logfile"
)

func runServe(args []string) error {
	fs := flag.NewFlagSet("serve", flag.ContinueOnError)
	addr := fs.String("addr", ":8080", "listen address")
	dataDir := fs.String("data", "", "directory for durable event data")
	if err := fs.Parse(args); err != nil {
		return err
	}
	if *dataDir == "" || fs.NArg() != 0 {
		fmt.Fprintln(os.Stderr, "usage: signalroom serve --addr <address> --data <directory>")
		os.Exit(2)
	}

	log, batches, err := logfile.Open(*dataDir)
	if err != nil {
		return err
	}
	defer log.Close()

	timeline := events.NewTimeline()
	for _, batch := range batches {
		for _, event := range batch {
			if err := timeline.Load(event); err != nil {
				return fmt.Errorf("recover events: %w", err)
			}
		}
	}
	timeline.SortAll()

	listener, err := net.Listen("tcp", *addr)
	if err != nil {
		return fmt.Errorf("listen on %s: %w", *addr, err)
	}

	server := &http.Server{
		Handler:           httpapi.NewHandler(timeline, log),
		ReadHeaderTimeout: 10 * time.Second,
	}
	serverErr := make(chan error, 1)
	go func() {
		serverErr <- server.Serve(listener)
	}()

	// Published exactly once the socket accepts connections; clients (and
	// tests) can wait on this line instead of polling with fixed sleeps.
	fmt.Printf("signalroom: listening on %s\n", listener.Addr())

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, os.Interrupt, syscall.SIGTERM)
	select {
	case sig := <-stop:
		fmt.Fprintf(os.Stderr, "signalroom: received %s, shutting down\n", sig)
	case err := <-serverErr:
		if !errors.Is(err, http.ErrServerClosed) {
			return fmt.Errorf("serve: %w", err)
		}
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := server.Shutdown(shutdownCtx); err != nil {
		return fmt.Errorf("shutdown: %w", err)
	}
	return nil
}

