408		entered := make(chan struct{})
409		release := make(chan struct{})
410		commitDone := make(chan struct{})
411		go func() {
412			_, err := tl.Ingest(batch, func(created []Event) error {
413				close(entered)
414				<-release
415				return nil
416			})
417			if err != nil {
418				t.Errorf("ingest: %v", err)
419			}
420			close(commitDone)
421		}()
422		<-entered
423	
424		// While the commit is in flight every compare must see either the empty
425		// timeline or the complete two-event batch — never one event, and never a
426		// response whose totals disagree with the sum of its segments.
427		done := make(chan struct{})
428		go func() {
