437				for _, segment := range result.Segments {
438					sumB += segment.BaselineCount
439					sumO += segment.ObservationCount
440				}
441				if sumB != result.BaselineTotal || sumO != result.ObservationTotal {
442					t.Errorf("totals disagree with segments: %+v", result)
443					return
444				}
445				if result.BaselineTotal != 0 && result.BaselineTotal != 2 {
446					t.Errorf("compare observed partial batch of %d", result.BaselineTotal)
447					return
448				}
449			}
450		}()
451		close(release)
452		<-commitDone
453		<-done
454	}
