23	func (f *fakeStorage) Append(batch []events.Event) error {
24		f.mu.Lock()
25		defer f.mu.Unlock()
26		if f.poisoned {
27			return errors.New("poisoned")
28		}
29		if f.failNext {
30			f.poisoned = true
31			f.failNext = false
32			return errors.New("simulated write failure")
