15	func getCompare(t *testing.T, server *httptest.Server, rawQuery string) (int, map[string]any) {
16		t.Helper()
17		resp, err := http.Get(server.URL + "/events/compare" + rawQuery)
18		if err != nil {
19			t.Fatalf("get compare: %v", err)
20		}
21		defer resp.Body.Close()
22		raw, err := io.ReadAll(resp.Body)
23		if err != nil {
24			t.Fatalf("read: %v", err)
25		}
26		var out map[string]any
27		if err := json.Unmarshal(raw, &out); err != nil {
28			t.Fatalf("decode %q: %v", raw, err)
29		}
30		return resp.StatusCode, out
31	}
32	
33	// withParam replaces the first occurrence of key=oldValue in the query.
34	func withParam(query, key, oldValue, newValue string) string {
35		return strings.Replace(query, key+"="+oldValue, key+"="+newValue, 1)
36	}
37	
38	func TestCompareResponseShapeAndCounts(t *testing.T) {
39		server, _, _ := newTestServer(t)
40		body := `{"events":[
41			{"id":"b1","service":"gateway","severity":"critical","message":"m","at":"2026-10-01T09:00:00.5Z"},
42			{"id":"b2","service":"gateway","severity":"info","message":"m","at":"2026-10-01T09:05:00Z"},
43			{"id":"o1","service":"gateway","severity":"critical","message":"m","at":"2026-10-01T10:00:00.25Z"},
44			{"id":"o2","service":"api","severity":"info","message":"m","at":"2026-10-01T10:02:00Z"},
45			{"id":"o3","service":"gateway","severity":"critical","message":"m","at":"2026-10-01T10:09:59.999999999Z"}
46		]}`
47		if status, _ := post(t, server, body); status != http.StatusOK {
48			t.Fatal("seed")
49		}
50	
51		status, out := getCompare(t, server, goodCompareQuery)
52		if status != http.StatusOK {
53			t.Fatalf("status=%d body=%v", status, out)
54		}
55		if out["baseline_total"].(float64) != 2 || out["observation_total"].(float64) != 3 {
56			t.Fatalf("totals wrong: %v", out)
57		}
58		if out["difference"].(float64) != 1 {
59			t.Fatalf("difference: %v", out["difference"])
60		}
61		ratio, ok := out["ratio"].(float64)
62		if !ok || ratio != 0.5 {
63			t.Fatalf("ratio must be numeric 0.5, got %v", out["ratio"])
64		}
65	
66		segments := out["segments"].([]any)
67		if len(segments) != 3 {
68			t.Fatalf("ten minutes / 240s must give three segments, got %d", len(segments))
69		}
70		first := segments[0].(map[string]any)
71		if first["baseline_since"] != "2026-10-01T09:00:00Z" ||
72			first["baseline_until"] != "2026-10-01T09:04:00Z" ||
73			first["since"] != "2026-10-01T10:00:00Z" ||
74			first["until"] != "2026-10-01T10:04:00Z" {
75			t.Fatalf("first segment boundaries wrong: %v", first)
76		}
77		if first["baseline_count"].(float64) != 1 || first["observation_count"].(float64) != 2 ||
78			first["difference"].(float64) != 1 {
79			t.Fatalf("first segment counts wrong: %v", first)
80		}
81		middle := segments[1].(map[string]any)
82		if middle["baseline_since"] != "2026-10-01T09:04:00Z" ||
83			middle["baseline_until"] != "2026-10-01T09:08:00Z" {
84			t.Fatalf("middle segment boundaries wrong: %v", middle)
85		}
86		if middle["baseline_count"].(float64) != 1 || middle["observation_count"].(float64) != 0 {
87			t.Fatalf("middle segment counts wrong (b2 at 09:05): %v", middle)
88		}
89		last := segments[2].(map[string]any)
90		if last["baseline_since"] != "2026-10-01T09:08:00Z" ||
91			last["baseline_until"] != "2026-10-01T09:10:00Z" ||
92			last["since"] != "2026-10-01T10:08:00Z" ||
93			last["until"] != "2026-10-01T10:10:00Z" {
94			t.Fatalf("last (short) segment boundaries wrong: %v", last)
95		}
96		// The 09:59:59.999999999 nanoseconds-before-end event stays inside; the
97		// baseline side of the final short segment has no events.
98		if last["baseline_count"].(float64) != 0 || last["observation_count"].(float64) != 1 {
99			t.Fatalf("last segment counts wrong (o3 with nanos): %v", last)
