```go
package events

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
	"unicode/utf8"
)

// Label limits.
const (
	MaxLabels           = 32
	MaxLabelNameRunes   = 64
	MaxLabelValueRunes  = 256
	MaxLabelConditions  = 32
)

// LabelCondition is a normalized name=value filter on an event's labels.
type LabelCondition struct {
	Name  string
	Value string
}

// NormalizeLabels validates and normalizes an event's label map. Names and
// values are trimmed and must be non-empty afterwards; names and values are
// bounded in Unicode code points; at most MaxLabels labels are allowed.
// A nil or empty input yields nil (no labels).
func NormalizeLabels(raw map[string]string) (map[string]string, error) {
	if len(raw) == 0 {
		return nil, nil
	}
	if len(raw) > MaxLabels {
		return nil, &ValidationError{Reason: fmt.Sprintf("event may carry at most %d labels", MaxLabels)}
	}
	normalized := make(map[string]string, len(raw))
	for name, value := range raw {
		name = strings.TrimSpace(name)
		value = strings.TrimSpace(value)
		if name == "" {
			return nil, &ValidationError{Reason: "label name must be non-empty"}
		}
		if value == "" {
			return nil, &ValidationError{Reason: fmt.Sprintf("label %q value must be non-empty", name)}
		}
		if utf8.RuneCountInString(name) > MaxLabelNameRunes {
			return nil, &ValidationError{Reason: fmt.Sprintf("label name %q exceeds %d characters", name, MaxLabelNameRunes)}
		}
		if utf8.RuneCountInString(value) > MaxLabelValueRunes {
			return nil, &ValidationError{Reason: fmt.Sprintf("label value for %q exceeds %d characters", name, MaxLabelValueRunes)}
		}
		if _, dup := normalized[name]; dup {
			return nil, &ValidationError{Reason: fmt.Sprintf("duplicate label name %q after trimming", name)}
		}
		normalized[name] = value
	}
	return normalized, nil
}

// decodeLabelsStrict decodes a labels JSON object, rejecting non-string
// values and duplicate JSON keys.
func decodeLabelsStrict(raw json.RawMessage) (map[string]string, error) {
	if len(raw) == 0 || string(bytes.TrimSpace(raw)) == "null" {
		return nil, nil
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	tok, err := dec.Token()
	if err != nil {
		return nil, fmt.Errorf("decode labels: %w", err)
	}
	delim, ok := tok.(json.Delim)
	if !ok || delim != '{' {
		return nil, fmt.Errorf("labels must be a JSON object of string to string")
	}
	labels := make(map[string]string)
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil, fmt.Errorf("decode label name: %w", err)
		}
		key, ok := keyTok.(string)
		if !ok {
			return nil, fmt.Errorf("label name must be a string")
		}
		var value string
		if err := dec.Decode(&value); err != nil {
			return nil, fmt.Errorf("label %q value must be a string", key)
		}
		if _, dup := labels[key]; dup {
			return nil, fmt.Errorf("duplicate label name %q", key)
		}
		labels[key] = value
	}
	if _, err := dec.Token(); err != nil {
		return nil, fmt.Errorf("decode labels: %w", err)
	}
	// Reject trailing data inside the labels object.
	if tok, err := dec.Token(); err != io.EOF {
		if err == nil {
			return nil, fmt.Errorf("decode labels: unexpected trailing data %v", tok)
		}
		return nil, fmt.Errorf("decode labels: %w", err)
	}
	return labels, nil
}
