func ParseLabelConditions(raw []string) ([]LabelCondition, error) {
	if len(raw) > MaxLabelConditions {
		return nil, fmt.Errorf("at most %d label conditions are allowed", MaxLabelConditions)
	}
	conds := make([]LabelCondition, 0, len(raw))
	seen := make(map[string]struct{}, len(raw))
	for _, item := range raw {
		name, value, found := strings.Cut(item, "=")
		if !found {
			return nil, fmt.Errorf("label condition %q must be formatted as name=value", item)
		}
		name = strings.TrimSpace(name)
		value = strings.TrimSpace(value)
		if name == "" {
			return nil, fmt.Errorf("label condition name must be non-empty")
		}
		if value == "" {
			return nil, fmt.Errorf("label condition %q value must be non-empty", name)
		}
		if utf8.RuneCountInString(name) > MaxLabelNameRunes {
			return nil, fmt.Errorf("label name %q exceeds %d characters", name, MaxLabelNameRunes)
		}
		if utf8.RuneCountInString(value) > MaxLabelValueRunes {
			return nil, fmt.Errorf("label value for %q exceeds %d characters", name, MaxLabelValueRunes)
		}
		if _, dup := seen[name]; dup {
			return nil, fmt.Errorf("duplicate label condition %q", name)
		}
		seen[name] = struct{}{}
		conds = append(conds, LabelCondition{Name: name, Value: value})
	}
	return conds, nil
}

// labelsMatch reports whether labels satisfy every condition. A missing
// label or a different value fails; comparison is exact and case-sensitive.
func labelsMatch(labels map[string]string, conds []LabelCondition) bool {
	for _, cond := range conds {
		if labels[cond.Name] != cond.Value {
			return false
		}
	}
	return true
}
