type eventDTO struct {
	ID       string          `json:"id"`
	Service  string          `json:"service"`
	Severity string          `json:"severity"`
	Message  string          `json:"message"`
	At       time.Time       `json:"at"`
	Labels   json.RawMessage `json:"labels,omitempty"`
}

func MarshalBatch(batch []Event) ([]byte, error) {
	dtos := make([]eventDTO, len(batch))
	for i, event := range batch {
		dto := eventDTO{
			ID:       event.ID,
			Service:  event.Service,
			Severity: event.Severity,
			Message:  event.Message,
			At:       event.At,
		}
		if len(event.Labels) > 0 {
			raw, err := json.Marshal(event.Labels)
			if err != nil {
				return nil, fmt.Errorf("encode labels: %w", err)
			}
			dto.Labels = raw
		}
		dtos[i] = dto
	}
	return json.Marshal(dtos)
}

func DecodeBatch(data []byte) ([]Event, error) {
	...
	batch := make([]Event, len(dtos))
	for i, dto := range dtos {
		labels, err := decodeLabelsStrict(dto.Labels)
		if err != nil {
			return nil, fmt.Errorf("decode events array: %w", err)
		}
		batch[i] = Event{
			...
			Labels: labels,
		}
	}
	return batch, nil
}
